const syncProjectsToRegistry = async (projects: Array<{
  id: number;
  name: string;
  full_path?: string;
  group_path?: string;
  members_count?: number;
  members?: any[];
  last_activity_at?: string;
  parent_id?: number;
  visibility?: string;
}>): Promise<void> => {
