const getProjectInsightsHistoryById = async (projectId: number): Promise<any[]> => {
  const pool = getPool();
  
  const query = `
    SELECT 
      pi.uuid,
      pi.row_id,
      pi.insights_data,
      pi.final_user_score,
      pi.api_score,
      pi.combined_score,
      pi.created_at
    FROM project_insights pi
    JOIN projects p ON pi.project_uuid = p.uuid
    WHERE p.id = $1
    ORDER BY pi.created_at ASC;
  `;
  
  try {
    const result = await pool.query(query, [projectId]);
    return result.rows;
  } catch (error: any) {
    console.error('❌ Failed to get project insights history by ID:', error.message);
    throw error;
  }
}

const getAllProjectsWithInsights = async (): Promise<any[]> => {
  const pool = getPool();
  
  const query = `
    SELECT 
      p.uuid,
      p.name,
      p.full_path,
      pi.final_user_score,
      pi.api_score,
      pi.combined_score,
      pi.created_at as last_insight_date
    FROM projects p
    LEFT JOIN LATERAL (
      SELECT * FROM project_insights
      WHERE project_uuid = p.uuid
      ORDER BY created_at DESC
      LIMIT 1
    ) pi ON true
    ORDER BY p.name;
  `;
  
  try {
    const result = await pool.query(query);
    return result.rows;
  } catch (error: any) {
    console.error('❌ Failed to get all projects with insights:', error.message);
    throw error;
  }
}

