const getProjectsNeedingAttention = async (limit: number = 6): Promise<any[]> => {
  const pool = getPool();
  
  const query = `
    SELECT 
      p.id,
      p.uuid,
      p.name,
      p.full_path,
      pi.insights_data,
      pi.combined_score,
      pi.created_at
    FROM projects p
    INNER JOIN LATERAL (
      SELECT * FROM project_insights
      WHERE project_uuid = p.uuid
      ORDER BY created_at DESC
      LIMIT 1
    ) pi ON true
    WHERE pi.combined_score < 3
    ORDER BY pi.combined_score ASC
    LIMIT $1;
  `;
  
  try {
    const result = await pool.query(query, [limit]);
    return result.rows;
  } catch (error: any) {
    console.error('❌ Failed to get projects needing attention:', error.message);
    throw error;
  }
}

