}

const saveTimeToRestoreService = async (
  data: TimeToRestoreServiceInput
): Promise<TimeToRestoreService> => {
  const pool = getPool();
  
  // Calculate restore time in hours
  const startTime = new Date(data.start_time);
  const endTime = new Date(data.end_time);
  const restoreTimeHours = (endTime.getTime() - startTime.getTime()) / (1000 * 60 * 60);

  const query = `
    INSERT INTO time_to_restore_service (
      project_id,
      incident_id,
      start_time,
      end_time,
      restore_time_hours,
      description
    ) VALUES ($1, $2, $3, $4, $5, $6)
    RETURNING *
  `;

  const values = [
    data.project_id,
    data.incident_id,
    data.start_time,
    data.end_time,
    restoreTimeHours.toFixed(2),
    data.description || null,
  ];

  const result = await pool.query(query, values);
  return result.rows[0];
}

